  const strip=s=>s.replace(/[12]군|[123]루수|\\d선발|\\d+경기 \\d+이닝/g,'').replace(/OPS \\d?\\.\\d+|평균자책점 \\d+\\.\\d+|\\d+(\\.\\d)?이닝|\\d+(경기|타수|안타|홈런|자책|연승|연패|승|패|위|세|명|년|월|일)/g,''); const num=F.filter(x=>/\\d/.test(strip(x))); ok(!num.length,'숨은 값처럼 보이는 숫자: '+num.join(' / '));
