T('[검수 11-06j] 이직할 때 전 구단 연봉 미계약 선수는 미계약으로 남았다가 개막 이틀 전 중간 금액으로 마무리된다(11-09zzb)',()=>{ fresh(); const p=domestic(G.user).find(q=>!q.foreign); p.sal=7000; p.hold={off:10000,ask:18000,d:G.day}; G.contract={y:G.year,tid:G.user,ended:[],foreignEnd:[],foreignDrop:[],released:[],neg:{}}; contractHandOff(G.user); ok(p.hold&&p.sal===7000,'인계만으로 계약됨 '+p.sal); p.team=G.teams.find(t=>t.id!==G.user).id; holdDaily(G.cal.open-2); ok(!p.hold&&p.sal===14000,'연봉 '+p.sal); });
T('[신규 11-06] 팬 트럭 시위: 강도 3은 대응 결정과 구단주 압박, 강도 1은 구단이 무시한다',()=>{ fresh(); simTo(()=>period()==='season'&&G.day>G.cal.open+40); const C=team(G.user); C.trust=55; const b0=C.trust; const n0=(G.evs||[]).length;
  truckFire(3,null,{s:6,why:['10위','8연패'],st:8,rank:10,fan:20}); const e=(G.evs||[]).find(x=>x.k==='truck'&&!x.done); ok(e,'대응 결정 없음'); ok(C.trust===b0-3,'구단주 신뢰 '+b0+'→'+C.trust); const f0=G.pr.fan; evPick(e.id,2); ok(G.pr.fan<f0&&C.trust===b0-8,'무대응 구단주 신뢰 '+C.trust);
  const nE=(G.evs||[]).length; truckFire(1,null,{s:2,why:['9위'],st:2}); ok((G.evs||[]).length===nE,'가벼운 시위에 결정이 생김'); ok(G.truck.log[0].sev===1,''); });
