T('[공통 점검] 엔진에 잡힌 우리 포스트시즌 경기는 캘린더에도 나오고, 시리즈가 일찍 끝나 사라진 경기에는 직관 알림이 가지 않는다',()=>{ fresh(); const op=G.teams.find(t=>t.id!==G.user).id; G.ps={done:false,cur:{round:'wc',hi:G.user,lo:op,days:[G.day+1,G.day+2],homes:[G.user,G.user],gi:0}}; ok(psOursAt(G.day+2),'엔진이 2차전을 모름');
  const pr=period; period=()=>'post'; try{ gmPlans()[G.day+2]={k:'attend',x:'owner',done:false}; G.ps.cur={round:'spo',hi:G.teams[2].id,lo:G.teams[3].id,days:[G.day+2],homes:[G.teams[2].id],gi:0}; G.day+=1; const m0=G.mail.length; gmPlanDaily(); ok(!G.mail.slice(0,G.mail.length-m0+1).some(m=>/내일 직관/.test(m.t)),'사라진 경기 직관 알림'); } finally{ period=pr; } });
