T('[공통 점검] 같은 시즌 종료 세이브를 이직 전후로 결산해도 그 구단의 기존 스폰서 계약액이 같다',()=>{ fresh(); simTo(()=>G.cal&&G.day>G.cal.end&&!G.last); sponInit(); const S=JSON.stringify(G); const old=G.user;
  const k=Object.keys(G.spon.c||{}); if(!k.length){ G.spon.c={main:{co:'테스트',amt:9000,y0:G.year,until:G.year+1}}; } const S1=JSON.stringify(G); const got=()=>{ const f=(G.fin&&G.fin[G.year]&&G.fin[G.year][old])||null; return f; };
  const pr=()=>{ let v=0; try{ const sp=sponSettle(G.year,G.ps,old,G.user===old?G.spon:G.sponT[old]); v=sp.base; }catch(e){} return v; };
  G=JSON.parse(S1); const a=pr(); G=JSON.parse(S1); switchTeam(G.teams.find(t=>t.id!==old).id); const b=pr(); ok(a===b&&a>0,'계약액 '+a+' / 이직 뒤 '+b); G=JSON.parse(S); });
T('[공통 점검] 제의 메일에 적힌 부임 시점과 실제 구단 전환일이 같다(수락하면 바로)',()=>{ fresh(); const t=G.teams.find(x=>x.id!==G.user).id; jobOffer(t,false); const m=G.mail[0]; ok(/수락하면 바로/.test(m.b||m.body||''),'메일: '+(m.b||m.body||'').slice(-80)); jobAnswer(t,true); ok(G.user===t,'즉시 전환 아님'); });
