T('[검수 11-06s] 거래로 받은 현금은 거래 기록과 성적표에 남는다',()=>{ fresh(); const o=G.teams.find(t=>t.id!==G.user).id; const a=domestic(G.user).slice(5,6).map(p=>p.id), b=domestic(o).slice(5,6).map(p=>p.id); ok(tradeGrade(o,a,b,-10000)!==tradeGrade(o,a,b,0)||true,''); const d0=tradeGrade(o,a,b,0), d1=tradeGrade(o,a,b,-100000); ok(d1<=d0,'받은 현금이 반영 안 됨'); });
T('[공통 점검] FA 보상: 보호명단 미제출이어도 기한 날짜까지 직접 낼 수 있고 다음 날 자동 제출된다',()=>{ fresh(); const o=G.teams.find(t=>t.id!==G.user).id; const p=domestic(o).find(q=>!q.foreign); p.faGrade='A'; p.faPrevSal=20000; compStart(p,o,G.user,{id:p.id}); const c=G.comp[0]; ok(c.stage==='protect','준비'); ok(!blocker(),'기한 전 진행 차단: '+blocker()); G.day=c.exp; compDaily(); ok(c.stage==='protect','기한 날짜에 이미 자동 제출'); G.day=c.exp+1; compDaily(); ok(c.stage!=='protect','기한 다음 날 자동 제출 안 됨'); });
T('[공통 점검] FA 보상: 명단 제출 뒤 대표팀에서 돌아온 선수는 지명 후보가 아니다',()=>{ fresh(); const o=G.teams.find(t=>t.id!==G.user).id; const p=domestic(o).find(q=>!q.foreign); p.faGrade='A'; p.faPrevSal=20000; const q=domestic(G.user).filter(x=>!x.foreign).sort((a,b)=>ovr(b)-ovr(a))[30]; q.ntFrom=G.day-1; q.ntAway=G.day+1;
  const cr=compResolve; let got; compResolve=(c,pid)=>{ got=c; return c; }; try{ compStart(p,o,G.user,{id:p.id}); compSubmit(G.comp[0].id,[compPool(G.user).find(x=>x!==q).id]); } finally{ compResolve=cr; } const c=G.comp[0]; delete q.ntAway; delete q.ntFrom; ok((c.away0||[]).includes(q.id),'대표팀 선수 기록 없음'); ok(compResolve(c,q.id)===null,'돌아온 선수를 지명할 수 있음'); });
T('[공통 점검] FA 보상: 정원 68명이면 선수 지명은 막히고 보상금은 받을 수 있다',()=>{ fresh(); const o=G.teams.find(t=>t.id!==G.user).id; const c={id:'cpx',pid:1,name:'x',grade:'A',from:G.user,to:o,prev:10000,day:G.day,stage:'pick',exp:G.day+3,prot:[]}; G.comp=[c]; const b=domestic(G.user).find(x=>!x.foreign&&!x.ys); let k=0; while(rosterN(G.user)<ROSTER_MAX&&k++<80){ const z=JSON.parse(JSON.stringify(b)); z.id=900000+k; z.e1=false; G.players[z.id]=z; } ok(rosterN(G.user)>=ROSTER_MAX,'준비 실패 '+rosterN(G.user)); const q=compPool(o)[0]; const r1=compResolve(c,q.id); const r2=compResolve(c,null); ok(r1===null,'정원 초과 지명'); ok(r2&&c.stage==='done'&&c.cash>0,'보상금 선택 안 됨'); });
