  const f0=ovsForecast(p,o,50), l0=ovsLim(o); ok(acadUp()===''&&acadUp()===''&&acadLv()===2,'제휴 단계'); ok(t.cash===5000-1000,'현금 '+t.cash); ok(ovsLim(o)===l0+2,'인원'); const f1=ovsForecast(p,o,50); ok(f1.big>f0.big&&f1.inj<f0.inj,'성과·부상');
