  ok(opLevel(u)===0&&opPatience(u).includes('여유'),'처음부터 참을성이 없음'); opRun(u,ctx,a,[.99]); ok(opLevel(u)===1&&opPatience(u).includes('반기지'),'한 번 실패 뒤 단계가 그대로');
