  ok(opSt(G.user).prom.length===1&&opRecent(G.user).length===1,'저장 뒤 기록·약속이 사라짐'); const e=G.evs.find(x=>x.k==='opush'&&!x.done); ok(e,'저장 뒤 결정이 사라짐'); OP_TEST=[0]; evPick(e.id,e.data.args.indexOf('fan')); OP_TEST=null;
